"""Natural choice speech and text-only next animation, with immutable preview saves."""
from playwright.sync_api import sync_playwright,expect
READ="""async()=>{const db=await new Promise(r=>{const q=indexedDB.open('resale-game',2);q.onsuccess=()=>r(q.result)});const store=db.transaction('saves').objectStore('saves');const result=await Promise.all([new Promise(r=>{const q=store.getAllKeys();q.onsuccess=()=>r(q.result)}),new Promise(r=>{const q=store.getAll();q.onsuccess=()=>r(q.result)})]);db.close();return JSON.stringify(result)}"""
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox'])
 for w,h in [(320,568),(390,844),(1024,768)]:
  c=b.new_context(viewport={'width':w,'height':h});page=c.new_page();errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto('http://127.0.0.1:4182');page.get_by_role('button',name='새로 시작',exact=True).click();page.get_by_label('닉네임',exact=True).fill('대화테스트');page.get_by_role('button',name='이 캐릭터로 시작',exact=True).click();expect(page.get_by_role('heading',name='첫 정산까지',exact=True)).to_be_visible();before=page.evaluate(READ)
  assert page.evaluate("previewEvent('reservation')") is True;root=page.locator('[data-event-preview]');expect(root.get_by_role('heading',name='예약 문의',exact=True)).to_be_visible();frame=root.locator('.story-stage').bounding_box();root.get_by_role('button',name='스킵',exact=True).click();root.get_by_role('button',name='거래 조건 다시 묻기',exact=True).click();expect(root.locator('.story-line strong')).to_have_text('대화테스트');expect(root.locator('.story-line p')).to_have_text('예약해 두면 거래 조건은 어떻게 되나요?');assert root.locator('.story-stage').bounding_box()==frame
  label=root.locator('.story-next-label');expect(label).to_have_text('다음');assert label.evaluate('n=>getComputedStyle(n).animationName')=='story-next-pulse';assert label.evaluate('n=>getComputedStyle(n).animationDuration')=='1.6s';page.wait_for_function("Number(getComputedStyle(document.querySelector('[data-event-preview] .story-next-label')).opacity)<0.9");assert root.locator('.story-next').evaluate('n=>getComputedStyle(n).opacity')=='1';assert root.locator('.story-next').evaluate('n=>getComputedStyle(n).borderTopWidth')=='0px'
  if w==390:page.screenshot(path='work/event-question-speech-390.png')
  root.get_by_role('button',name='스킵',exact=True).click();root.get_by_role('button',name='잠시 예약해 두기',exact=True).click();expect(root.locator('.story-line strong')).to_have_text('대화테스트');expect(root.locator('.story-line p')).to_have_text('잠시 예약해 둘게요. 일정이 정해지면 다시 연락해 주세요.');root.get_by_role('button',name='다음',exact=True).click();expect(root.locator('.story-line strong')).not_to_have_text('대화테스트');root.get_by_role('button',name='계속하기',exact=True).click();expect(root).to_have_count(0);assert page.evaluate(READ)==before
  assert page.evaluate("previewEvent('bundle')") is True;root.get_by_role('button',name='스킵',exact=True).click();root.get_by_role('button',name='거래 취소',exact=True).click();expect(root.locator('.story-line p')).to_have_text('생각해 봤는데, 이번 거래는 하지 않을게요.');root.get_by_role('button',name='스킵',exact=True).click();root.get_by_role('button',name='계속하기',exact=True).click();expect(root).to_have_count(0);assert page.evaluate(READ)==before
  assert page.evaluate('document.documentElement.scrollWidth<=innerWidth') and not errors,errors;c.close();print(f'{w}x{h}: question/hold/cancel spoken sentences, hero then NPC, text-only pulse, stable stage/save PASS',flush=True)
 c=b.new_context(viewport={'width':390,'height':844},reduced_motion='reduce');page=c.new_page();page.goto('http://127.0.0.1:4182');expect(page.get_by_role('button',name='새로 시작',exact=True)).to_be_visible();assert page.evaluate('previewEnding()') is True;label=page.locator('[data-ending-preview] .story-next-label');expect(label).to_be_visible();assert label.evaluate('n=>getComputedStyle(n).animationName')=='none';assert label.evaluate('n=>getComputedStyle(n).opacity')=='1';page.locator('[data-ending-preview]').get_by_role('button',name='다음',exact=True).click();c.close();b.close();print('Reduced motion: next stays static and clickable PASS',flush=True)
